import numba
from scipy.optimize import linear_sum_assignment

@numba.njit(cache=True)
def make_G(N, row_ind, col_ind):
    G = np.zeros((N, N), dtype=np.float64)
    val = 1.0 / N
    for i in range(N):
        G[row_ind[i], col_ind[i]] = val
    return G

